-- GENERATED by scripts/near_me_data_to_sql.py -- do not edit by hand.
-- ZIP centers: U.S. Census Bureau 2024 Gazetteer: ZIP Code Tabulation Areas (ZCTA) internal points (ZCTAs 530xx-549xx (Wisconsin)), retrieved 2026-09-26.
-- City centers: U.S. Census Bureau 2024 Gazetteer: Places (Wisconsin) internal points, retrieved 2026-09-26.
-- Clinics: HRSA Data Warehouse: Health Center Service Delivery and Look-Alike Sites (Site State = WI; excludes school-based sites (setting "School" or "school" in the site name) and mobile vans), retrieved 2026-09-26.




-- Hospitals (CMS has no coordinates): use the ZIP center, else the center of the city with that name.
update hospitals h
set latitude = z.latitude, longitude = z.longitude
from zip_centers z
where z.zip = left(h.postal_code, 5);

update hospitals h
set latitude = p.latitude, longitude = p.longitude
from place_centers p
where h.latitude is null and lower(p.name) = lower(h.city) and p.state = h.state;
